(function(root){
'use strict';
function sections(r){const m=r.metrics,n=(x)=>x||0,sum=o=>Object.values(o).reduce((a,b)=>a+b,0);return [
 ['The run', [['Play time',Math.floor(r.time/60)+' min '+Math.floor(r.time%60)+' s'],['Final radius',r.radius],['Waves launched',m.wavesStarted],['Waves cleared',m.wavesCompleted],['Monsters still alive',r.monsters],['Bonuses chosen',r.artifacts?.length||0]]],
 ['Combat', [['Monsters spawned',n(m.created.monster)],['Monsters defeated',r.kills],['Damage dealt to monsters',n(m.damage.monster)],['Damage taken by your side',sum(m.damage)-n(m.damage.monster)],['Locomotive shots',n(m.shots.train)],['Soldier shots',n(m.shots.actor)],['Enemy shots',n(m.shots.monster)],['Collisions',r.collisions]]],
 ['Soldiers', [['Soldiers recruited',n(m.created.actor)],['Soldiers lost',n(m.lost.actor)],['Surviving soldiers',r.population.total],['Aboard',r.population.aboard],['On foot',r.population.walking],['Available seats',r.population.seats-r.population.aboard],['Convoy capacity',r.population.seats],['Soldier limit',r.population.limit],['Boardings',m.boardings],['Damage taken by soldiers',n(m.damage.actor)]]],
 ['The convoy', [['Locomotive HP',Math.ceil(r.train.hp)+' / '+r.train.maxHp],['Distance travelled (units)',m.distance],['Laps of the circle',m.distance/(2*Math.PI*6.95)],['Average speed (units/s)',r.time?m.distance/r.time:0],['Carriages created (including 3 initial)',n(m.created.wagon)],['Carriages produced by houses',m.wagonsProduced],['Carriages destroyed',n(m.lost.wagon)],['Remaining carriages',r.wagons],['Damage taken by locomotive',n(m.damage.train)],['Damage taken by carriages',n(m.damage.wagon)]]],
 ['The village', [['Houses built (including initial)',n(m.created.building)],['Houses destroyed',n(m.lost.building)],['Standing houses',r.buildings],['HP regenerated',m.regenerated],['Damage taken by houses',n(m.damage.building)]]],
 ['Defeated monsters',Object.entries(root.RoundCircleSimulation?.types||{}).map(([id,t])=>[t.name,n(m.killsByType[id])])],
 ['Stacked bonuses',Object.entries(r.bonuses).map(([id,value])=>[root.RoundCircleRewards?.effects[id]||id,'×'+value.toLocaleString('en-CA')])]
 ];}
function resolveOutcome(profile,flags,records,state){if(!profile)return null;if(state.train.hp<=0)return 'defeat';if(state.radius<6-1e-9)return null;const harmony=profile.endings.harmony;if(state.buildings>=harmony.minBuildings&&harmony.requiredFlags.every(flag=>flags[flag]===true))return 'harmony';if(records.some(record=>record.waveId===profile.endings.force.waveId&&record.done))return 'force';return 'departure';}
function install(){const {sim,designer}=root.roundCircleLab,dialog=document.createElement('dialog');dialog.className='endgame';dialog.setAttribute('aria-labelledby','endgame-title');document.body.append(dialog);dialog.addEventListener('cancel',e=>e.preventDefault());let result;
 const element=(tag,text,parent)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;parent?.append(e);return e;};
 function finish(reason='radius'){if(sim.ended)return;const lab=root.roundCircleLab,profile=lab.currentRunProfile;if(reason!=='defeat')sim.cfg.vortexRadius=6;const dialogue=lab.features?.dialogue,flags=dialogue?.exportFlags?.()||{},choices=(dialogue?.history||[]).filter(entry=>entry.choice).map(entry=>({dialogueId:entry.dialogueId,node:entry.nodeId,choice:entry.choice,text:entry.text})),waves=designer.runner.records.map(record=>({waveId:record.waveId,name:record.name,done:record.done,startedAt:record.startedAt,completedAt:record.completedAt}));const outcome=resolveOutcome(profile,flags,waves,{train:{hp:sim.train.hp},radius:sim.cfg.vortexRadius,buildings:sim.buildings.filter(building=>building.hp>0&&!building.dead).length});result=sim.finishRun({artifacts:lab.features?.rewards.artifacts||[],runId:profile?.id||null,endReason:reason,plannedWaves:profile?.waves.waves.length||sim.metrics.wavesStarted,outcome,narrative:{flags,choices},waves});
  const explanation=root.RoundCircleFinale.describe(reason,outcome,sim.metrics.wavesStarted);
  const ending=profile?.endings[outcome];dialog.className='endgame'+(outcome?' endgame-'+outcome:'');dialog.replaceChildren();element('p',ending?.eyebrow||'THE CIRCLE HAS CLOSED',dialog).className='endgame-eyebrow';element('h1',ending?.title||'Run complete',dialog).id='endgame-title';element('p',ending?.text||'The vortex has reached its maximum size. Here is your run report.',dialog);
  element('p',explanation.cause+' '+(reason==='defeat'?'Final locomotive HP: 0 / '+Math.round(sim.train.maxHp)+'.':'Final radius: 6 / 6. Locomotive HP: '+Math.ceil(sim.train.hp)+' / '+Math.round(sim.train.maxHp)+'.')+' Waves cleared: '+sim.metrics.wavesCompleted+' / '+(profile?.waves.waves.length||sim.metrics.wavesStarted)+'.',dialog).className='endgame-cause';
  if(profile&&reason!=='defeat'){const met=profile.endings.harmony.requiredFlags.filter(key=>flags[key]===true).length;element('p','Shared-home choices: '+met+' / '+profile.endings.harmony.requiredFlags.length+'. Standing houses: '+result.buildings+' (at least '+profile.endings.harmony.minBuildings+' required). '+(outcome==='harmony'?'Both conditions were met: the vortex closes without taking the village.':'The conditions for harmony were not met; clearing waves alone cannot stop the vortex.'),dialog).className='endgame-cause';}
  const actions=element('div',undefined,dialog);actions.className='row';const restart=element('button','New run',actions);restart.className='primary';restart.onclick=()=>{dialog.close();document.querySelector('#start').click();};
  root.RoundCircleScreen?.addExitButton(actions);const download=element('button','Export run report JSON',actions);download.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=element('a');a.href=url;a.download='round-circle-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  root.RoundCircleDashboard.render(dialog,result,sections(result));
  lab.waveFeedback?.clear();const show=()=>{dialog.showModal();restart.focus();};if(lab.finale)lab.finale.start({reason,outcome,wave:sim.metrics.wavesStarted,onComplete:show});else show();
 }
 const previous=sim.onReset;sim.onReset=()=>{previous?.();root.roundCircleLab.finale?.reset();dialog.close();result=null;};root.roundCircleEnd={finish};
}
root.RoundCircleEndgame={sections,resolveOutcome};if(typeof module!=='undefined')module.exports=root.RoundCircleEndgame;
if(typeof window!=='undefined')window.addEventListener('round-circle-ready',install,{once:true});
})(typeof window!=='undefined'?window:globalThis);
